import {bettingOptions,bettingAmounts,bettingPresets} from './betting.js';
import {captureMotion,animateCards,revealMotion} from './motion.js';
const root=document.querySelector('#app');
const state={profile:null,auth:{workos:false},room:null,network:{},source:null,connected:false,busy:false,modal:null,peek:false,betting:null,tableView:false,initial:true};
const path=location.pathname.split('/').filter(Boolean),code=(path[1]||'').toUpperCase(),isDisplay=path[0]==='table',isRoom=path[0]==='room',isJoin=path[0]==='join',isDeck=path[0]==='deck';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const n=v=>Number(v||0).toLocaleString('en-US');
const suitName={S:'spades',H:'hearts',D:'diamonds',C:'clubs'},suitGlyph={S:'♠',H:'♥',D:'♦',C:'♣'};
const titleCase=s=>s?.charAt(0).toUpperCase()+s?.slice(1);
let toastTimer;
function toast(message){const el=document.querySelector('#toast');el.textContent=message;el.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('visible'),4500);}
async function api(url,body){const res=await fetch(url,{method:body===undefined?'GET':'POST',headers:body===undefined?{}:{'Content-Type':'application/json'},body:body===undefined?undefined:JSON.stringify(body)});const data=await res.json();if(!res.ok)throw Error(data.error||'Request failed.');return data;}
function card(id,cls='',key=''){const visible=!!id;const value=visible?id:'back';const label=visible?`${id[0]==='T'?'10':id[0]} of ${suitName[id.at(-1)]}`:'Face-down card';const hero=cls.includes('hero');const lazy=/^(gallery-|demo-|promo-)/.test(key);return `<span class="card ${cls}" data-card="${esc(key||id||'back')}" role="img" aria-label="${esc(label)}"><span class="card-fallback" aria-hidden="true">${visible?(id[0]==='T'?'10':id[0])+suitGlyph[id.at(-1)]:'♠'}</span><img src="/cards/play/${value}-320.webp" srcset="/cards/play/${value}-320.webp 320w, /cards/play/${value}-640.webp 640w" sizes="${hero?'(max-width:750px) 210px, 290px':cls.includes('own')?'180px':'(max-width:750px) 110px, 160px'}" alt="" width="320" height="448" draggable="false" decoding="async" ${lazy?'loading="lazy"':hero?'fetchpriority="high"':''}></span>`;}
const icon=`<svg viewBox="0 0 24 24" width="24" height="24" aria-hidden="true"><path d="M12 2C9 7 3 8 3 13a5 5 0 0 0 8 4c0 3-1 4-3 5h8c-2-1-3-2-3-5a5 5 0 0 0 8-4c0-5-6-6-9-11Z" fill="currentColor"/></svg>`;
function profileControl(){return state.profile?`<button class="text-button" data-do="profile">${esc(state.profile.name)}<span class="profile-dot">${esc(state.profile.name.slice(0,1))}</span></button>`:`<button class="text-button" data-do="login">Sign in</button>`;}
function shell(content,extra=''){return `<div class="shell ${extra}"><header><a href="/" class="brand" aria-label="Partydeck home"><img class="brand-logo" src="/brand/partydeck-small.webp" alt="Partydeck" width="184" height="69"></a><div class="header-right">${profileControl()}</div></header>${content}<footer><span>Good cards. Better company.</span><a href="/deck">The deck</a><span>Play chips only</span></footer></div>`;}
function home(){return shell(`<main class="landing"><section class="home"><div class="home-copy"><h1>Deal<br>everyone in.</h1><p class="intro">Texas Hold’em and blackjack.<br>A table full of friends. Your hand on your phone.</p><div class="home-actions"><button class="primary large" data-do="create">Start a table <span>↗</span></button><a class="text-button how-link" href="#how-it-works">How it works <span>↓</span></a></div><form id="quick-join" class="quick-join"><label for="quick-code">Already have a table?</label><div class="code-entry"><input id="quick-code" name="quickCode" aria-label="Room code" placeholder="Enter room code" maxlength="6" minlength="6" autocomplete="off" autocapitalize="characters" spellcheck="false" required><button type="submit" aria-label="Join a table">Join <span>↗</span></button></div></form><p class="quiet-note">No download. No account needed to play.</p></div><div class="hero-cards" aria-label="Our original playing card deck">${card(null,'hero-back','hero-back')}${card('KS','hero-king','hero-k')}${card('QH','hero-queen','hero-q')}<span class="hero-caption">Your next card night.</span></div></section>
<section class="how-section" id="how-it-works"><div class="section-heading"><h2>Same room.<br>Everyone’s in.</h2><p>Put the table where everyone can see it.<br>Keep your cards close.</p></div><div class="how-layout"><div class="device-scene" aria-label="A shared table and a private phone hand"><div class="demo-screen"><span>Friday’s table <i></i></span><div class="demo-board">${['AS','KH','QC'].map(c=>card(c,'demo-card','demo-'+c)).join('')}</div><small>Pot &nbsp; 240</small></div><div class="demo-phone"><span>Your hand</span><div>${card('KS','demo-card','demo-private-k')}${card('QS','demo-card','demo-private-q')}</div><strong>Hold to peek</strong></div></div><ol class="how-steps"><li><span>1</span><div><h3>Pick a game.</h3><p>Start a table on a laptop, TV browser or phone.</p></div></li><li><span>2</span><div><h3>Let everyone join.</h3><p>Scan the QR code or share the six-character room code.</p></div></li><li><span>3</span><div><h3>Play from your phone.</h3><p>Private cards, simple controls. We shuffle, deal and count the chips.</p></div></li></ol></div></section>
<section class="games-section"><div class="section-heading"><h2>Two ways<br>to spend the evening.</h2><p>Just play chips.<br>Keep the competition friendly.</p></div><div class="game-panels"><button class="game-panel poker-panel" data-do="choose-poker"><div class="panel-cards">${card('AS','','promo-as')}${card('KS','','promo-ks')}</div><div><span class="game-count">2–8 players</span><h3>Texas Hold’em <span>↗</span></h3><p>Read the table. Back your hand.</p></div></button><button class="game-panel blackjack-panel" data-do="choose-blackjack"><div class="panel-cards">${card('AH','','promo-ah')}${card('JC','','promo-jc')}</div><div><span class="game-count">1–8 players</span><h3>Blackjack <span>↗</span></h3><p>You and your friends against the dealer.</p></div></button></div></section>
<section class="objects-section"><img src="/art/table-objects-cutout-960.webp" srcset="/art/table-objects-cutout-640.webp 640w, /art/table-objects-cutout-960.webp 960w" sizes="(max-width:750px) calc(100vw - 44px), (max-width:1440px) 46vw, 620px" alt="A matte black deck and poker chips" width="1536" height="1024" loading="lazy" decoding="async"><div><h2>A card night.<br>Less setup.</h2><p>No deck to find. No chips to count. Start a table and pass the invitation around.</p><p>No spare screen? Switch to phone-only mode and keep the whole table on your phones.</p><a class="text-button" href="/deck">Explore the deck <span>↗</span></a></div></section>
<section class="faq-section"><h2>Before the first hand.</h2><div><details><summary>Does everyone need an account?</summary><p>No. Join with a nickname and play. Save a profile when you want to keep your statistics and achievements.</p></details><details><summary>Can we play without a big screen?</summary><p>Yes. Choose “I’m playing here” when starting a table. The table and controls will appear on each player’s phone.</p></details><details><summary>Is this real money?</summary><p>No. Every game uses virtual chips with no cash value. There are no deposits or withdrawals.</p></details><details><summary>What if someone disconnects?</summary><p>Their seat is held for 30 seconds. They can reopen the same link on the same browser to return.</p></details></div></section><section class="closing-section"><span aria-hidden="true">♠</span><h2>Who’s dealing?</h2><button class="primary large" data-do="create">Start your table <span>↗</span></button></section></main>`,'landing-shell');}
function entry(join=false){
 const mode=state.createMode||(matchMedia('(max-width: 750px)').matches?'phones':'shared');const display=!join&&mode==='shared';const selected=state.createGame||'poker';
 const deviceIcon=phone=>phone?'<span class="device-icon phone-icon" aria-hidden="true"></span>':'<span class="device-icon screen-icon" aria-hidden="true"></span>';
 return shell(`<main class="entry entry-layout ${join?'join-entry':''}"><section class="entry-content"><a class="back-link" href="/">← Back</a><h1>${join?'Take a seat.':'Make it a card night.'}</h1><form id="${join?'join-form':'create-form'}">${join?`<label class="join-code-label">Room code<input name="code" class="code-input" value="${esc(state.joinCode||code)}" placeholder="ABCDEF" maxlength="6" minlength="6" autocomplete="off" autocapitalize="characters" spellcheck="false" required></label>`:`<fieldset class="game-picker"><legend>What are we playing?</legend><div class="choice-row"><label class="choice game-choice"><input type="radio" name="game" value="poker" ${selected==='poker'?'checked':''}><span><span class="choice-art">${card('KS','','choice-ks')}${card('AS','','choice-as')}</span><strong>Texas Hold’em</strong><small>2–8 players</small></span></label><label class="choice game-choice"><input type="radio" name="game" value="blackjack" ${selected==='blackjack'?'checked':''}><span><span class="choice-art">${card('AH','','choice-ah')}${card('JC','','choice-jc')}</span><strong>Blackjack</strong><small>1–8 players · Auto dealer</small></span></label></div></fieldset><fieldset class="device-picker"><legend>This device</legend><label class="mode-choice"><input type="radio" name="mode" value="shared" ${display?'checked':''}>${deviceIcon(false)}<span><strong>Table screen only</strong><small>Everyone joins and plays on their own phone.</small></span><span class="selection-check" aria-hidden="true">✓</span></label><label class="mode-choice"><input type="radio" name="mode" value="phones" ${!display?'checked':''}>${deviceIcon(true)}<span><strong>I’m playing here</strong><small>Host and play here. No extra screen needed.</small></span><span class="selection-check" aria-hidden="true">✓</span></label></fieldset>`}<div class="entry-fields"><div id="player-fields" ${display?'hidden':''}>${!state.profile?`<label>Your name<input name="name" autocomplete="nickname" maxlength="24" placeholder="Your nickname" required ${display?'disabled':''}></label>`:`<p class="signed-player"><span class="avatar">${esc(state.profile.name[0])}</span>Playing as ${esc(state.profile.name)}</p>`}</div>${!join?'<label>Table name<input name="tableName" value="Partydeck" maxlength="28"></label>':''}</div><button class="primary large full create-submit" type="submit">${join?'Join table':'Create table'} <span>→</span></button><p class="form-error" role="alert"></p></form></section></main>`,'setup-shell');
}
function board(r){if(r.game==='blackjack'){const bj=r.blackjack;return `<div class="dealer-zone"><span class="muted">Dealer${bj?.phase==='complete'?' · '+total(bj.dealer):''}</span><div class="board-cards">${(bj?.dealer??[null,null]).map((c,i)=>card(c,'','dealer-'+i+'-'+c)).join('')}</div></div>`;}return `<div class="pot"><span>Pot</span><strong>${n(r.pot)}</strong></div><div class="board-cards">${Array.from({length:5},(_,i)=>r.board[i]?card(r.board[i],'','board-'+i+'-'+r.board[i]):'<span class="card-slot" aria-label="Undealt community card"></span>').join('')}</div>`;}
function total(cards){let x=0,a=0;for(const c of cards||[]){if(!c)continue;if(c[0]==='A'){x+=11;a++;}else x+=['T','J','Q','K'].includes(c[0])?10:Number(c[0]);}while(x>21&&a--){x-=10;}return x;}
function connectionTag(p){if(p.connected)return '';if(!p.seated)return '<span class="seat-status">Disconnected</span>';return `<span class="seat-status" data-offline="${p.offlineSince}">Reconnecting…</span>`;}
function table(r,compact=false){if(r.game==='blackjack')return blackjackTable(r);const players=r.players.filter(p=>p.seated);return `<section data-players="${players.length}" class="table-stage ${compact?'compact':''} ${r.game==='blackjack'?'blackjack-table':''}"><div class="table-outline"></div><div class="table-centre">${board(r)}</div>${players.map((p,i)=>{const count=players.length,angle=-Math.PI/2+2*Math.PI*i/count;const x=Math.cos(angle).toFixed(5),y=Math.sin(angle).toFixed(5);const bj=r.blackjack?.players.find(q=>q.id===p.id);return `<div class="seat ${r.activeId===p.id?'active':''} ${r.phase==='complete'&&r.results.some(x=>x.id===p.id&&(r.game==='poker'||x.amount>0))?'winner':''}" style="--seat-x:${x};--seat-y:${y}"><div class="seat-meta"><span class="avatar">${esc(p.name[0])}</span><div><strong>${esc(p.name)}</strong><span>${n(p.stack)}</span></div>${p.seat===r.button&&r.game==='poker'?'<b class="dealer-chip">D</b>':''}</div>${connectionTag(p)}<div class="seat-cards">${r.game==='poker'?(p.hasCards&&!p.lastAction.includes('Fold')?(p.cards||[null,null]).map((c,j)=>card(c,'mini',p.id+j+c)).join(''):''):bj?bj.hands.map((h,j)=>`<div class="public-bj-hand">${h.cards.map((c,k)=>card(c,'mini',p.id+j+k+c)).join('')}<span>${h.total}</span></div>`).join(''):''}</div><span class="seat-action">${esc(p.lastAction|| (p.pending?'Next hand':p.bet?'Bet '+n(p.bet):''))}</span></div>`;}).join('')}</section>`;}
function blackjackTable(r){
 const players=r.players.filter(p=>p.seated),cols=players.length<=3?players.length:Math.ceil(players.length/2);
 return `<section class="table-stage blackjack-table" data-players="${players.length}" style="--bj-columns:${Math.max(1,cols)}"><div class="table-centre">${board(r)}</div><div class="blackjack-seats">${players.map(p=>{
  const bj=r.blackjack?.players.find(x=>x.id===p.id),settled=r.phase==='complete'?r.results.filter(x=>x.id===p.id):[],net=settled.reduce((sum,x)=>sum+x.amount,0);
  const outcome=settled.length?(net>0?'Won +'+n(net):net<0?'Lost '+n(-net):'Push'):p.lastAction|| (p.pending?'Next hand':'');
  return `<div class="seat ${r.activeId===p.id?'active':''} ${settled.length&&net>0?'winner':''}"><div class="seat-meta"><span class="avatar">${esc(p.name[0])}</span><div><strong>${esc(p.name)}</strong><span>${n(p.stack)}</span></div></div>${connectionTag(p)}<div class="seat-cards">${bj?bj.hands.map((h,j)=>`<div class="public-bj-hand"><div class="hand-fan" style="--cards:${h.cards.length}">${h.cards.map((c,k)=>card(c,'mini',p.id+'-'+j+'-'+k+'-'+c)).join('')}</div><strong class="public-total">${h.total}${h.total>21?' · Bust':''}</strong></div>`).join(''):''}</div><span class="seat-action ${settled.length?'settled':''}">${esc(outcome)}</span></div>`;
 }).join('')}</div></section>`;
}
function wagerLobby(r){
 const players=r.players.filter(p=>p.seated),eligible=players.filter(p=>p.connected&&p.stack>=2),ready=eligible.filter(p=>p.betReady).length;
 return `<main class="wager-lobby"><h2>${isDisplay?'Place your bets.':r.me?.betReady?'Your bet is in.':'Choose your bet.'}</h2><p class="wager-progress" role="status">${ready} of ${eligible.length} ready</p>${!isDisplay&&r.me?.stack>=2?`<div class="wager-choice"><strong>${n(r.me.bet)} <span>chips</span></strong><button class="${r.me.betReady?'text-button':'primary'}" data-do="edit-bet">${r.me.betReady?'Change bet':'Choose bet'}</button></div>`:!isDisplay?'<p class="muted">Request more chips in the table menu to join.</p>':''}<div class="wager-players">${players.map(p=>`<div><span class="avatar">${esc(p.name[0])}</span><strong>${esc(p.name)}</strong><span class="${p.betReady?'bet-ready':''}">${!p.connected?'Reconnecting':p.stack<2?'Sitting out':p.betReady?'Ready ✓':'Choosing'}</span></div>`).join('')}</div>${!isDisplay?hostNext(r):'<p class="muted">The host deals when everyone is ready.</p>'}</main>`;
}
function roundTabs(){return `<nav class="round-tabs" aria-label="Game view"><button data-do="hand-view" aria-pressed="${!state.tableView}">Your hand</button><button data-do="table-view" aria-pressed="${state.tableView}">Table</button></nav>`;}
function roomHeader(r){return `<header class="room-header"><div><a class="brand" href="/">${icon}</a><div><h1>${esc(r.name)}</h1><span class="muted">${r.game==='poker'?'Texas Hold’em · 10 / 20':'Blackjack · Dealer stands on 17'}</span></div></div><div class="room-tools"><span class="connection-dot ${state.connected?'online':''}" title="${state.connected?'Connected':'Reconnecting'}"></span><button class="secondary" data-do="invite">Invite <span>↗</span></button>${!isDisplay?'<button class="icon-button" data-do="menu" aria-label="Table menu">···</button>':''}</div></header>`;}
function nextHandText(r){const host=r.players.find(p=>p.id===r.hostId);return r.me?.isHost?'Ready for the next hand?':`Waiting for ${host?.name||'the host'} to deal the next hand.`;}
function results(r){
 if(r.phase!=='complete')return '';
 const mine=r.results.filter(x=>x.id===r.me?.id),delta=r.me?.handDelta;
 let title,detail,amount='';
 if(r.game==='poker'){
  const winners=[...new Set(r.results.map(x=>x.name))];const names=winners.join(' & ');
  title=r.me?(mine.length?(winners.length>1?'You won a share.':'You won the hand.'):'This hand went to '+names+'.'):(winners.length>1?names+' share the pots.':names+' wins.');
  detail=r.results.map(x=>`${x.name}: ${x.label.toLowerCase()} · ${n(x.amount)} chips`).join(' / ');
  if(r.me&&delta!==null&&delta!==undefined)amount=(delta>0?'+':'')+n(delta)+' chips';
  else amount=n(r.results.reduce((sum,x)=>sum+x.amount,0))+' chips awarded';
 }else{
  const rows=r.me?mine:r.results;const net=rows.reduce((sum,x)=>sum+x.amount,0);
  title=r.me?(net>0?'You won.':net<0?'Dealer wins.':rows.every(x=>x.result==='push')?'Push. Your bet is returned.':'Even for this hand.'):'Hand complete.';
  if(r.me&&rows.some(x=>x.result==='blackjack'))title='Blackjack!';
  detail=rows.map(x=>`${r.me?'':x.name+': '}${titleCase(x.label)}${rows.length>1?' · '+(x.amount>0?'+':'')+n(x.amount):''}`).join(' / ');
  amount=r.me&&net!==0?(net>0?'+':'')+n(net)+' chips':'';
  if(!r.me)detail='';
 }
 return `<div class="results result-summary ${r.me&&Number(delta)<0?'loss':'win'}" role="status" aria-live="polite"><strong>${esc(title)}</strong>${amount?`<span class="result-amount">${esc(amount)}</span>`:''}${detail?`<span class="result-detail">${esc(detail)}</span>`:''}${isDisplay?`<span class="next-hand-note">${esc(nextHandText(r))}</span>`:''}</div>`;
}
function turnText(r){if(r.paused)return 'Table paused';if(!state.connected)return 'Reconnecting…';if(r.phase==='complete')return r.me?.isHost?(r.game==='blackjack'?'Choose bets for the next hand':'Deal when everyone is ready'):nextHandText(r);if(r.me?.pending)return 'You’ll join the next hand';if(r.activeId===r.me?.id)return 'Your turn';const active=r.players.find(p=>p.id===r.activeId);return active?`${active.name} is playing`:'The dealer is playing';}
function roundStatus(r){if(r.phase==='lobby')return '';return `<div class="round-status"><span class="stage-pill">${esc(r.stage||'Hand '+r.handNumber)}</span><span>Hand ${r.handNumber}</span>${r.game==='blackjack'&&r.phase==='complete'&&isDisplay?'':`<strong>${esc(turnText(r))}</strong>`}</div>${r.lastEvent&&r.phase==='playing'?`<div class="activity-line" aria-live="polite">${esc(r.lastEvent.name)} ${esc(r.lastEvent.action.toLowerCase())}</div>`:''}`;}
function lobby(r){
  const players=r.players.filter(p=>p.seated),host=players.find(p=>p.id===r.hostId);
  return `<section class="lobby invite-lobby"><div class="lobby-title"><h2>${isDisplay?'Join the table.':r.me?.isHost?'Invite your friends.':'You’re in.'}</h2><p class="muted">${isDisplay?(host?`${esc(host.name)} starts the game from their phone.`:'Scan to join. The first player becomes the host.'):r.me?.isHost?'You’re hosting. Start when everyone is here.':`${esc(host?.name||'Your host')} will start the game.`}</p></div><div class="invite-centre"><img class="lobby-qr" src="/api/rooms/${r.code}/qr" alt="QR code to join the table"><strong class="room-code">${r.code}</strong><div class="invite-actions"><button class="primary" data-do="share">Invite friends ↗</button><button class="secondary" data-do="copy">Copy link</button></div><input class="invite-link" aria-label="Invitation link" value="${esc(joinUrl(r))}" readonly></div><div class="lobby-players">${players.length?players.map(p=>`<div><span class="avatar">${esc(p.name[0])}</span><strong>${esc(p.name)}${p.id===r.hostId?'<small class="host-label">Host</small>':''}</strong><small>${p.connected?'Ready':'Connecting…'}</small></div>`).join(''):'<p class="muted">Waiting for players to join.</p>'}</div>${!isDisplay?hostNext(r):''}</section>`;
}
function hostNext(r){
 if(!r.me?.isHost)return '';
 const players=r.players.filter(p=>p.seated&&p.connected&&p.stack>=(r.game==='poker'?1:2)),minimum=r.game==='poker'?2:1;
 const pending=r.phase==='betting'?players.filter(p=>!p.betReady).length:0;
 const reason=r.paused?'Resume the table to continue.':!state.connected?'Reconnecting…':r.mode==='shared'&&!r.displayConnected?'Connect the table screen to start.':players.length<minimum?`Waiting for ${minimum-players.length} more player${minimum-players.length===1?'':'s'}.`:pending?`Waiting for ${pending} bet${pending===1?'':'s'}.`:'';
 const prepare=r.game==='blackjack'&&r.phase!=='betting';
 return `<div class="lobby-start"><div class="host-next"><button class="primary large" data-command="${prepare?'prepare':'start'}" ${reason||state.busy?'disabled':''}>${r.phase==='betting'?'Deal hand':r.phase==='complete'?'Next hand':'Start game'} <span>→</span></button></div>${reason?`<p class="start-hint" role="status">${reason}</p>`:''}</div>`;
}
function hand(r){const me=r.me;if(!me)return '';if(!me.seated)return `<section class="empty-state"><h2>Your seat was released.</h2><p>Your ${n(me.stack)} chips are saved for this session.</p><button class="primary" data-do="rejoin">Rejoin table</button></section>`;if(r.phase==='lobby')return '';let actions=me.legal.actions;return `<section class="private-hand"><div class="hand-status ${r.activeId===me.id?'your-turn':''}" aria-live="polite"><i></i>${esc(turnText(r))}</div><div class="private-spacer">${r.mode==='shared'?'<span class="muted">The table is on the shared screen.</span>':''}</div><div class="hand-content">${r.game==='poker'?`<div class="own-cards">${(me.cards.length?me.cards:[null,null]).map((c,i)=>card(state.peek?c:null,'own',`own-${i}-${state.peek?c:'back'}`)).join('')}</div><button class="peek-control" id="peek" aria-label="Hold to reveal your cards" aria-pressed="${state.peek}">Hold to peek</button>`:`<div class="blackjack-hands">${me.hands.map((h,i)=>`<div class="bj-hand ${r.me.activeHand===i&&r.activeId===me.id?'current':''}"><div class="own-cards hand-fan" style="--cards:${h.cards.length}">${h.cards.map((c,k)=>card(c,'own','bj-'+i+k+c)).join('')}</div><strong class="hand-total">${h.total}</strong><span class="muted">${h.result?esc(titleCase(h.result)):'Bet '+n(h.bet)}</span></div>`).join('')}</div>`}<div class="own-stack">${n(me.stack)} <span>chips</span></div></div>${results(r)}<div class="action-dock"><div class="turn-label ${r.activeId===me.id?'your-action':''}">${esc(turnText(r))}${r.phase==='playing'&&r.activeId===me.id?`<span class="turn-caption">${r.game==='blackjack'?'Hit to take a card. Stand to keep your hand.':me.legal.call?`Call ${n(me.legal.call)} to stay in this hand.`:'You can check without adding chips.'}</span>`:''}</div><div class="action-buttons">${actions.map(a=>['raise','bet'].includes(a)?`<button class="secondary" data-do="raise" ${!state.connected||state.busy?'disabled':''}>${titleCase(a)}</button>`:`<button class="${['call','check','hit'].includes(a)?'primary':'secondary'}" data-action="${a}" ${!state.connected||state.busy?'disabled':''}>${titleCase(a)}${a==='call'?' '+n(me.legal.call):['double','split'].includes(a)?' +'+n(me.hands[me.activeHand]?.bet):''}</button>`).join('')}</div>${r.phase==='complete'?`${hostNext(r)}`:''}</div></section>`;}
function room(){const r=state.room;if(!r)return state.error?`<main class="empty-state"><h2>Couldn’t join this table.</h2><p>${esc(state.error)}</p><a class="secondary" href="/">Back home</a></main>`:`<main class="loading"><span class="spinner"></span><p>Connecting to the table…</p></main>`;if(r.phase==='closed')return shell(`<main class="entry"><h1>That was<br>a good hand.</h1><p>Session complete. Your statistics are saved.</p><button class="primary large" data-do="profile">View your profile</button><a class="secondary large" href="/">Back home</a></main>`);return `<div class="room-shell ${isDisplay?'display-screen':'player-screen'} ${r.game==='blackjack'?'blackjack-room':''} ${['playing','complete','betting'].includes(r.phase)?'round-screen':''} ${r.phase==='complete'?'round-complete':''} ${r.mode==='phones'&&!isDisplay?'phones-mode':''}">${roomHeader(r)}${!state.connected?'<div class="connection-banner" role="status">Reconnecting… Your seat is reserved briefly. Actions are unavailable.</div>':''}${r.notice?`<div class="notice" role="status">${esc(r.notice)}</div>`:''}${r.paused&&r.me?.isHost?'<div class="resume"><button class="secondary" data-command="pause">Resume table</button></div>':''}${r.me&&!r.me.seated?hand(r):r.phase==='lobby'?lobby(r):r.phase==='betting'?wagerLobby(r):r.game==='blackjack'?`${!isDisplay&&r.mode==='phones'?roundTabs():''}${isDisplay||r.mode==='phones'&&state.tableView?roundStatus(r)+table(r):hand(r)}`:`${isDisplay||r.mode==='phones'?roundStatus(r)+table(r,!isDisplay):''}${isDisplay?results(r):hand(r)}`}${isDisplay?`<div class="display-footer"><span>Room <strong>${r.code}</strong></span><span>${r.phase==='playing'?'Hand '+r.handNumber:r.phase==='complete'?esc(nextHandText(r)):'Ready when you are'}</span><button class="text-button" data-do="fullscreen">Full screen ⛶</button></div>`:''}</div>`;}
function joinUrl(r){const base=state.network.publicUrl||(['localhost','127.0.0.1'].includes(location.hostname)?state.network.localUrl:null)||location.origin;return base+'/join/'+r.code;}
async function copyInvite(){
  const url=joinUrl(state.room);
  try{if(navigator.clipboard?.writeText){await navigator.clipboard.writeText(url);toast('Invite link copied.');return;}}catch{}
  const input=document.createElement('textarea');input.value=url;input.style.cssText='position:fixed;left:-9999px;top:0';document.body.append(input);input.select();let copied=false;try{copied=document.execCommand('copy');}catch{}input.remove();
  if(copied)toast('Invite link copied.');else{setModal('invite');toast('Press and hold the invitation link to copy it.');}
}
function openBetting(kind){
 if(!state.connected||state.busy)return;
 const options=bettingOptions(state.room,kind);if(!options)return;
 state.betting={kind,key:options.key,amount:String(options.initial),error:''};setModal('betting',root.querySelector(kind==='poker'?'[data-do=raise]':'[data-do=edit-bet]'));
}
function bettingModal(){
 const options=bettingOptions(state.room,state.betting?.kind);if(!options)return '';
 const blackjack=options.kind==='blackjack',title=blackjack?'Choose your bet':options.action==='raise'?'Raise to':'Place a bet';
 return `<div class="modal-backdrop betting-backdrop ${blackjack?'blackjack-betting':''}"><section class="modal betting-modal" role="dialog" aria-modal="true" aria-labelledby="bet-title" tabindex="-1"><header class="betting-header"><h2 id="bet-title">${title}</h2><button class="close" data-do="close-modal" aria-label="Close betting">×</button></header><form id="betting-form" novalidate><div class="betting-body"><div class="betting-amount"><input id="bet-amount" name="betAmount" value="${esc(state.betting.amount)}" type="text" inputmode="numeric" pattern="[0-9]*" maxlength="10" autocomplete="off" spellcheck="false" aria-labelledby="bet-title" aria-describedby="bet-unit bet-error"><span id="bet-unit">${blackjack?'chips on the next hand':'chips total this round'}</span></div><input class="bet-slider" name="betSlider" type="range" aria-label="Choose chip amount" min="${options.min}" max="${options.max}" step="${options.step}" value="${esc(state.betting.amount)}"><div class="bet-limits"><span>Min ${n(options.min)}</span><span>Max ${n(options.max)}</span></div><div class="bet-presets" aria-label="Quick amounts">${bettingPresets(options).map(p=>`<button type="button" data-bet-amount="${p.amount}" aria-label="${p.label===String(p.amount)?p.label:p.label+', '+n(p.amount)} chips" aria-pressed="false">${p.label}</button>`).join('')}</div><dl class="bet-breakdown">${!blackjack?`<div><dt>Already in this round</dt><dd>${n(options.committed)}</dd></div>`:''}<div class="bet-added"><dt>${blackjack?'Your bet':'You add'}</dt><dd data-bet-added></dd></div><div><dt>${blackjack?'Left after the deal':'Left in your stack'}</dt><dd data-bet-remaining></dd></div></dl></div><div class="betting-footer"><p id="bet-error" class="bet-error" role="status" aria-live="polite"></p><button class="primary bet-confirm" type="submit"></button><button class="text-button bet-cancel" type="button" data-do="close-modal">Cancel</button></div></form></section></div>`;
}
function syncBetting(){
 const backdrop=root.querySelector('.betting-backdrop'),draft=state.betting;
 if(!backdrop||!draft)return;
 const options=bettingOptions(state.room,draft.kind);if(!options)return;
 const amounts=bettingAmounts(options,draft.amount),blocked=!state.connected||state.busy;
 const input=backdrop.querySelector('#bet-amount'),slider=backdrop.querySelector('.bet-slider');
 if(input.value!==draft.amount)input.value=draft.amount;
 input.setAttribute('aria-invalid',String(!amounts.valid));input.disabled=state.busy;
 slider.value=String(Math.max(options.min,Math.min(options.max,Number(draft.amount)||options.min)));
 slider.disabled=blocked||options.min===options.max;
 slider.style.setProperty('--bet-progress',`${options.max===options.min?100:(Number(slider.value)-options.min)/(options.max-options.min)*100}%`);
 slider.setAttribute('aria-valuetext',`${n(slider.value)} chips total`);
 backdrop.querySelector('[data-bet-added]').textContent=amounts.valid?n(amounts.added)+' chips':'—';
 backdrop.querySelector('[data-bet-remaining]').textContent=amounts.valid?(amounts.remaining===0?'0 · All in':n(amounts.remaining)):'—';
 backdrop.querySelectorAll('[data-bet-amount]').forEach(button=>{button.disabled=blocked;button.setAttribute('aria-pressed',String(amounts.valid&&Number(button.dataset.betAmount)===amounts.amount));});
 const error=!state.connected?'Reconnecting. Your amount is saved.':draft.error||(!amounts.valid?`Choose ${options.step===2?'an even number':'a whole number'} from ${n(options.min)} to ${n(options.max)}.`:'');
 backdrop.querySelector('#bet-error').textContent=error;
 const submit=backdrop.querySelector('.bet-confirm');submit.disabled=blocked||!amounts.valid;
 submit.textContent=state.busy?'Confirming…':options.kind==='blackjack'?`${state.room.phase==='betting'?'Confirm bet':'Set bet'}${amounts.valid?' · '+n(amounts.amount):''}`:`${options.action==='raise'?'Raise to':'Bet'}${amounts.valid?' '+n(amounts.amount):''}${amounts.remaining===0?' · All in':''}`;
 backdrop.querySelector('form').setAttribute('aria-busy',String(state.busy));
 updateBettingViewport();
}
function bindBetting(){
 const backdrop=root.querySelector('.betting-backdrop');if(!backdrop||backdrop.dataset.bound)return;
 backdrop.dataset.bound='true';
 const change=value=>{if(!state.betting||state.busy)return;state.betting.amount=value;state.betting.error='';syncBetting();};
 const input=backdrop.querySelector('#bet-amount');
 input.addEventListener('input',()=>change(input.value));
 input.addEventListener('focus',()=>input.select());
 backdrop.querySelector('.bet-slider').addEventListener('input',e=>change(e.target.value));
 backdrop.querySelectorAll('[data-bet-amount]').forEach(el=>el.addEventListener('click',()=>change(el.dataset.betAmount)));
 backdrop.querySelectorAll('[data-do="close-modal"]').forEach(el=>el.addEventListener('click',()=>setModal(null)));
 backdrop.addEventListener('click',e=>{if(e.target===backdrop)setModal(null);});
 backdrop.querySelector('form').addEventListener('submit',e=>{
  e.preventDefault();const draft=state.betting,options=bettingOptions(state.room,draft?.kind);
  if(!options||options.key!==draft.key||!state.connected||state.busy)return;
  const value=bettingAmounts(options,draft.amount);if(!value.valid){input.focus();return;}
  command(options.kind==='blackjack'?'bet':'action',{action:options.action,amount:value.amount});
 });
}
function updateBettingViewport(){
 const sheet=root.querySelector('.betting-backdrop');if(!sheet)return;
 sheet.style.setProperty('--dialog-height',`${window.visualViewport?.height||innerHeight}px`);
 sheet.style.setProperty('--dialog-top',`${window.visualViewport?.offsetTop||0}px`);
}
window.visualViewport?.addEventListener('resize',updateBettingViewport);
window.visualViewport?.addEventListener('scroll',updateBettingViewport);

function modal(){if(!state.modal)return '';if(state.modal==='betting')return bettingModal();const r=state.room;let content='';
  if(state.modal==='invite'&&r)content=`<h2>Pull up a chair.</h2><p class="muted">Scan with your phone or enter the room code.</p><img class="qr" src="/api/rooms/${r.code}/qr" alt="QR code to join"><strong class="room-code">${r.code}</strong><button class="primary full" data-do="copy">Copy invite link</button><input class="invite-link" aria-label="Invitation link" value="${esc(joinUrl(r))}" readonly>${r.mode==='shared'?`<a class="secondary full" href="/table/${r.code}" target="_blank" rel="noopener">Open shared display ↗</a>`:''}`;
  if(state.modal==='login')content=state.auth.workos?`<div class="auth-heading"><span aria-hidden="true">♠</span><h2>Your seat is saved.</h2><p>Sign in to keep your statistics and achievements across devices.</p></div><a class="primary full" href="/auth/login?returnTo=${encodeURIComponent(location.pathname)}">Continue to sign in <span>↗</span></a><a class="secondary full" href="/auth/login?signup=1&returnTo=${encodeURIComponent(location.pathname)}">Create an account</a><button class="text-button full" data-do="close-modal">Keep playing as a guest</button><details class="legacy-login"><summary>Have an older username account?</summary><form id="login-form"><label>Username<input name="username" autocomplete="username" required></label><label>Password<input name="password" type="password" autocomplete="current-password" required></label><button class="primary full" type="submit">Sign in</button><p class="form-error" role="alert"></p></form></details>`:`<h2>Welcome back.</h2><form id="login-form"><label>Username<input name="username" autocomplete="username" required></label><label>Password<input name="password" type="password" autocomplete="current-password" required></label><button class="primary full" type="submit">Sign in</button><p class="form-error" role="alert"></p></form>`;
  if(state.modal==='profile'&&state.profile){const p=state.profile;content=`<h2>${esc(p.name)}</h2><p class="muted">${p.authProvider==='workos'?'Your saved profile':p.username?'@'+esc(p.username):'Your guest profile'}</p><div class="stats"><div><strong>${n(p.stats.hands)}</strong><span>Hands played</span></div><div><strong>${n(p.stats.wins)}</strong><span>Hands won</span></div><div><strong>${n(p.stats.sessions)}</strong><span>Sessions</span></div></div><h3>Achievements</h3><div class="achievements">${p.achievements.map(([id,name,desc])=>`<div class="achievement ${p.stats.achievements.includes(id)?'earned':''}"><span>${p.stats.achievements.includes(id)?'✦':'◇'}</span><div><strong>${esc(name)}</strong><small>${esc(desc)}</small></div></div>`).join('')}</div>${!p.authProvider&&state.auth.workos?`<a class="primary full" href="/auth/login?signup=1&returnTo=${encodeURIComponent(location.pathname)}">Save your profile ↗</a>`:!p.username&&!p.authProvider?`<details><summary>Save your profile</summary><p class="small muted">Choose a username and password to keep your progress on other devices. No email required. Keep your password safe; email recovery is not available.</p><form id="register-form"><label>Username<input name="username" autocomplete="username" minlength="3" maxlength="24" pattern="[a-zA-Z0-9_]+" required></label><label>Password<input name="password" type="password" autocomplete="new-password" minlength="10" maxlength="128" required></label><button class="primary full">Save profile</button><p class="form-error" role="alert"></p></form></details>`:''}${!isRoom?'<button class="text-button" data-do="logout">Sign out</button>':''}`;}
  if(state.modal==='menu'&&r){content=`<h2>Table settings</h2><p class="muted">${esc(r.name)} · ${r.code}</p>${r.me.isHost?`<div class="settings-actions"><button class="secondary" data-command="pause">${r.paused?'Resume':'Pause'} table</button><button class="secondary" data-command="mode" data-mode="${r.mode==='shared'?'phones':'shared'}">${r.mode==='shared'?'Switch to phone-only mode':'Use a shared screen'}</button>${r.phase!=='playing'?`<button class="secondary" data-command="game" data-game="${r.game==='poker'?'blackjack':'poker'}">Switch to ${r.game==='poker'?'blackjack':'Texas Hold’em'}</button>`:''}</div><h3>Players</h3>${r.players.filter(p=>p.seated).map(p=>`<div class="manage-player"><span>${esc(p.name)}<small>${n(p.stack)} chips${r.rebuyRequests.includes(p.id)?' · Rebuy requested':''}</small></span><div>${p.stack<2000?`<button class="text-button" data-command="rebuy" data-player="${p.id}" ${r.phase==='playing'?'disabled':''}>Refill</button>`:''}${p.id!==r.me.id&&p.connected?`<button class="text-button" data-command="transfer" data-player="${p.id}">Make host</button>`:''}</div></div>`).join('')}<button class="danger" data-do="end-confirm" ${r.phase==='playing'?'disabled':''}>End session</button>`:`<button class="secondary full" data-command="rebuy-request">Request a rebuy</button>${!r.players.find(p=>p.id===r.hostId)?.connected?'<button class="secondary full" data-command="claim-host">Take over as host</button>':''}`}<button class="secondary full" data-do="profile">My profile</button><button class="text-button full" data-command="leave" ${r.phase==='playing'?'disabled':''}>Leave table</button><p class="small muted">Rebuys and leaving are available between hands.</p>`;}
  if(state.modal==='end-confirm')content='<h2>End this session?</h2><p>Everyone will leave the table. Profile statistics stay saved.</p><button class="danger full" data-command="end">End session</button>';
  return `<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-label="${esc(state.modal)}" tabindex="-1"><button class="close" data-do="close-modal" aria-label="Close dialog">×</button>${content}</section></div>`;
}
function deck(){return shell(`<main class="deck-page"><div class="deck-heading"><h1>The deck.</h1><p class="muted">52 original card faces. One shared back.</p></div>${['S','H','D','C'].map(s=>`<section><h2>${suitGlyph[s]} ${titleCase(suitName[s])}</h2><div class="deck-grid">${['A','2','3','4','5','6','7','8','9','T','J','Q','K'].map(r=>`<figure>${card(r+s,'','gallery-'+r+s)}<figcaption>${r==='T'?'10':r}${suitGlyph[s]}</figcaption></figure>`).join('')}</div></section>`).join('')}<section><h2>Card back</h2><div class="deck-grid"><figure>${card(null,'','gallery-back')}<figcaption>Shared back</figcaption></figure></div></section></main>`);}
function render(){
 const previousBetting=root.querySelector('.betting-backdrop');
 if(state.modal==='betting'&&bettingOptions(state.room,state.betting?.kind)?.key!==state.betting?.key){state.modal=null;state.betting=null;if(!state.busy)toast('The table changed. Check your available actions.');}
 const existingHero=root.querySelector('.hero-cards');captureMotion(root);
 const active=document.activeElement;const restore=active?.name?{name:active.name,value:active.value,start:active.selectionStart,end:active.selectionEnd}:null;
 const content=isDeck?deck():isRoom||isDisplay?room():isJoin?entry(true):state.page==='create'?entry(false):state.page==='join'?entry(true):home();
 // Never detach an open editor: iOS would dismiss its keyboard during a presence update.
 const keepEditor=previousBetting&&state.modal==='betting';
 if(keepEditor){const template=document.createElement('template');template.innerHTML=content;root.firstElementChild.replaceWith(template.content.firstElementChild);}
 else root.innerHTML=content+modal();
 const newHero=root.querySelector('.hero-cards');if(existingHero&&newHero)newHero.replaceWith(existingHero);
 document.documentElement.classList.toggle('has-modal',!!state.modal);root.firstElementChild.inert=!!state.modal;
 if(restore&&!(keepEditor&&previousBetting.contains(active))){const el=root.querySelector(`[name="${CSS.escape(restore.name)}"]`);if(el){el.value=restore.value;el.focus({preventScroll:true});try{el.setSelectionRange(restore.start,restore.end);}catch{}}}
 bind();syncBetting();
 if(state.modal&&!root.querySelector('.modal')?.contains(document.activeElement))root.querySelector('.modal')?.focus({preventScroll:true});
 animate();window.render_game_to_text=()=>JSON.stringify({screen:isDisplay?'table':isRoom?'player':isDeck?'deck':state.page||'home',connected:state.connected,room:state.room?{...state.room,me:state.room.me?{...state.room.me,cards:state.peek?state.room.me.cards:state.room.me.cards.map(()=>null)}:null}:null});
}
let motionObserver;
function animate(){
 motionObserver?.disconnect();
 animateCards(root,state.room);
 if(matchMedia('(prefers-reduced-motion: reduce)').matches)return;
 motionObserver=new IntersectionObserver(entries=>{for(const entry of entries)if(entry.isIntersecting){entry.target.classList.add('in-view');motionObserver.unobserve(entry.target);}},{threshold:.1});
 root.querySelectorAll('.how-section,.games-section,.objects-section,.faq-section,.closing-section').forEach(el=>motionObserver.observe(el));
}
let modalReturn=null;
function setModal(name,opener=document.activeElement){
 if(name&&!state.modal){const el=opener;modalReturn=el?.dataset.do?`[data-do="${el.dataset.do}"]`:null;}
 state.modal=name;if(name!=='betting')state.betting=null;state.peek=false;render();
 if(name)root.querySelector('.modal')?.focus({preventScroll:true});else if(modalReturn)root.querySelector(modalReturn)?.focus({preventScroll:true});
}
async function command(name,args={}){
 if(state.busy)return;state.busy=true;render();
 try{
  const result=await api(`/api/rooms/${code}/command`,{command:name,args,version:state.room.version,requestId:crypto.randomUUID?.()||String(Date.now())+Math.random()});
  if(state.modal==='betting'&&['bet','action'].includes(name)){state.modal=null;state.betting=null;}
  if(result.room)receiveRoom(result);if(name==='leave')location.href='/';
  if(['game','mode','transfer','end'].includes(name))state.modal=null;
 }catch(e){if(state.betting){state.betting.error=e.message;syncBetting();}else toast(e.message);}
 finally{state.busy=false;render();}
}
async function runForm(form,fn){const error=form.querySelector('.form-error');const button=form.querySelector('button[type="submit"],button.primary');if(button)button.disabled=true;try{await fn(new FormData(form));}catch(e){if(error)error.textContent=e.message;else toast(e.message);}finally{if(button)button.disabled=false;}}
function bind(){
  root.querySelectorAll('[data-do]:not(.betting-backdrop [data-do])').forEach(el=>el.addEventListener('click',async()=>{const a=el.dataset.do;if(a==='create'||a==='join'||a.startsWith('choose-')){state.page=a.startsWith('choose-')?'create':a;if(a.startsWith('choose-'))state.createGame=a.slice(7);render();window.scrollTo({top:0,behavior:'instant'});}else if(['login','profile','invite','menu','end-confirm'].includes(a))setModal(a);else if(a==='close-modal')setModal(null);else if(a==='hand-view'||a==='table-view'){state.tableView=a==='table-view';state.peek=false;render();}else if(a==='raise'||a==='edit-bet')openBetting(a==='raise'?'poker':'blackjack');else if(a==='copy')await copyInvite();else if(a==='share'){if(navigator.share){try{await navigator.share({title:state.room.name,text:'Join our table',url:joinUrl(state.room)});}catch(e){if(e.name!=='AbortError')await copyInvite();}}else setModal('invite');}else if(a==='logout'){const result=await api('/api/logout',{});state.profile=null;setModal(null);if(result.logoutUrl)location.href=result.logoutUrl;}else if(a==='rejoin'){try{await api(`/api/rooms/${code}/join`,{});connect();}catch(e){toast(e.message);}}else if(a==='fullscreen'){if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen();}}));
  root.querySelectorAll('[data-command]').forEach(el=>el.addEventListener('click',()=>command(el.dataset.command,{mode:el.dataset.mode,game:el.dataset.game,playerId:el.dataset.player})));
  root.querySelectorAll('[data-action]').forEach(el=>el.addEventListener('click',()=>command('action',{action:el.dataset.action})));
  root.querySelectorAll('[name=mode]').forEach(el=>el.addEventListener('change',()=>{state.createMode=el.value;const fields=root.querySelector('#player-fields');fields.hidden=el.value==='shared';fields.querySelectorAll('input').forEach(input=>input.disabled=fields.hidden);}));
  root.querySelectorAll('.invite-link').forEach(el=>el.addEventListener('click',()=>el.select()));
  const form=id=>root.querySelector('#'+id);
  form('quick-join')?.addEventListener('submit',e=>{e.preventDefault();state.joinCode=new FormData(e.currentTarget).get('quickCode').trim().toUpperCase();state.page='join';render();window.scrollTo({top:0,behavior:'instant'});root.querySelector('[name=name]')?.focus();});
  root.querySelectorAll('[name=game]').forEach(el=>el.addEventListener('change',()=>{state.createGame=el.value;}));
  form('create-form')?.addEventListener('submit',e=>{e.preventDefault();runForm(e.currentTarget,async f=>{const displayOnly=f.get('mode')==='shared';if(!displayOnly&&!state.profile)state.profile=(await api('/api/guest',{name:f.get('name')})).profile;const r=await api('/api/rooms',{name:f.get('tableName'),game:f.get('game'),mode:f.get('mode'),displayOnly});location.href=(r.view==='display'?'/table/':'/room/')+r.code;});});
  form('join-form')?.addEventListener('submit',e=>{e.preventDefault();runForm(e.currentTarget,async f=>{if(!state.profile)state.profile=(await api('/api/guest',{name:f.get('name')})).profile;const c=f.get('code').trim().toUpperCase();await api(`/api/rooms/${c}/join`,{});location.href='/room/'+c;});});
  for(const action of ['login','register'])form(action+'-form')?.addEventListener('submit',e=>{e.preventDefault();runForm(e.currentTarget,async f=>{state.profile=(await api('/api/'+action,{username:f.get('username'),password:f.get('password')})).profile;setModal(action==='register'?'profile':null);toast(action==='register'?'Profile saved.':'Signed in.');});});
  bindBetting();
  const peek=form('peek');if(peek){const show=()=>{if(state.peek)return;state.peek=true;window.gsap?.killTweensOf(root.querySelectorAll('.own-cards .card'));const cards=state.room.me.cards;root.querySelector('.own-cards').innerHTML=cards.map((c,i)=>card(c,'own','peek-'+i)).join('');peek.setAttribute('aria-pressed','true');peek.textContent='Release to hide';revealMotion(root.querySelectorAll('.own-cards .card'),true);};const hide=()=>{if(!state.peek)return;state.peek=false;window.gsap?.killTweensOf(root.querySelectorAll('.own-cards .card'));root.querySelector('.own-cards').innerHTML=state.room.me.cards.map(()=>card(null,'own')).join('');peek.setAttribute('aria-pressed','false');peek.textContent='Hold to peek';revealMotion(root.querySelectorAll('.own-cards .card'),false);};peek.addEventListener('pointerdown',e=>{e.preventDefault();peek.setPointerCapture(e.pointerId);show();});for(const event of ['pointerup','pointercancel','lostpointercapture','blur'])peek.addEventListener(event,hide);peek.addEventListener('keydown',e=>{if(e.code==='Space'||e.code==='Enter'){e.preventDefault();show();}});peek.addEventListener('keyup',hide);}
  root.querySelector('.modal-backdrop:not(.betting-backdrop)')?.addEventListener('click',e=>{if(e.target===e.currentTarget)setModal(null);});
}
function receiveRoom(data){
  if(state.room&&data.room.version<state.room.version)return;
  const previousPhase=state.room?.phase;
  const refreshProfile=data.room.phase==='complete'&&state.room?.phase!=='complete';
  const changed=!state.connected||!state.room||state.room.version!==data.room.version;
  state.room=data.room;
  if(state.room.phase==='betting'&&previousPhase!=='betting'&&!state.room.me?.betReady){const options=bettingOptions(state.room,'blackjack');if(options){state.betting={kind:'blackjack',key:options.key,amount:String(options.initial),error:''};state.modal='betting';}}
  if(state.room.phase==='playing'&&previousPhase!=='playing')state.tableView=false;
  if(data.profile)state.profile=data.profile;state.connected=true;
  if(changed){state.peek=false;for(const c of state.room.me?.cards||[]){const img=new Image();img.src='/cards/play/'+c+'-320.webp';img.srcset='/cards/play/'+c+'-320.webp 320w, /cards/play/'+c+'-640.webp 640w';img.sizes='180px';}render();}
  if(refreshProfile&&state.profile)api('/api/me').then(d=>{state.profile=d.profile;if(state.modal==='profile')render();}).catch(()=>{});
}
function connect(){
  state.source?.close();
  if(state.network.transport==='poll'){
    let stopped=false,timer,controller;const client=crypto.randomUUID();
    const suffix=`?client=${client}${isDisplay?'&view=display':''}`;
    const poll=async()=>{
      if(stopped)return;controller=new AbortController();const timeout=setTimeout(()=>controller.abort(),10000);
      try{const response=await fetch(`/api/rooms/${code}/poll${suffix}`,{signal:controller.signal});const data=await response.json();if(!response.ok)throw Error(data.error);if(!stopped)receiveRoom(data);}
      catch(e){if(!stopped){if(state.connected){state.connected=false;state.peek=false;render();}else if(!state.room){state.error=e.message;render();}}}
      finally{clearTimeout(timeout);if(!stopped)timer=setTimeout(poll,1000);}
    };
    state.source={close:()=>{stopped=true;clearTimeout(timer);controller?.abort();},poll:()=>{clearTimeout(timer);if(!controller||controller.signal.aborted)poll();}};
    window.addEventListener('pagehide',()=>{state.source?.close();navigator.sendBeacon(`/api/rooms/${code}/disconnect${isDisplay?'?view=display':''}`,new Blob([JSON.stringify({client})],{type:'application/json'}));},{once:true});
    poll();return;
  }
  state.source=new EventSource(`/api/rooms/${code}/stream${isDisplay?'?view=display':''}`);
  state.source.onmessage=e=>receiveRoom(JSON.parse(e.data));
  state.source.onerror=()=>{state.connected=false;state.peek=false;render();};
}
window.addEventListener('pageshow',e=>{if(e.persisted&&(isRoom||isDisplay))connect();});
document.addEventListener('visibilitychange',()=>{if(document.hidden&&state.peek){state.peek=false;render();}});
window.addEventListener('blur',()=>{if(state.peek){state.peek=false;render();}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){setModal(null);}if(e.key==='Tab'&&state.modal){const els=[...root.querySelectorAll('.modal button,.modal a,.modal input,.modal summary')].filter(e=>!e.disabled&&e.getClientRects().length);if(!els.length)return;const first=els[0],last=els.at(-1);if(e.shiftKey&&(document.activeElement===first||document.activeElement.classList.contains('modal'))){e.preventDefault();last.focus();}else if(!e.shiftKey&&(document.activeElement===last||document.activeElement.classList.contains('modal'))){e.preventDefault();first.focus();}}if(e.key==='f'&&isDisplay&&!['INPUT','TEXTAREA'].includes(e.target.tagName)){if(document.fullscreenElement)document.exitFullscreen();else document.documentElement.requestFullscreen();}});
setInterval(()=>{for(const el of document.querySelectorAll('[data-offline]')){const seconds=Math.max(0,Math.ceil(((Number(el.dataset.offline)||Date.now())+(state.room?.graceMs||30000)-Date.now())/1000));el.textContent=seconds?`Reconnecting · ${seconds}s`:'Disconnected';}},1000);
window.advanceTime=ms=>new Promise(resolve=>setTimeout(resolve,Math.min(ms,1000)));
render();
try{const [auth,network]=await Promise.all([api('/api/me'),api('/api/network')]);state.profile=auth.profile;state.auth=auth.auth||{workos:false};state.network=network;if(isRoom&&!state.profile){location.replace('/join/'+code);}else if(isRoom||isDisplay){if(isRoom)await api(`/api/rooms/${code}/join`,{});else {const check=await fetch(`/api/rooms/${code}/qr`);if(!check.ok)throw Error('This room is unavailable. Check the code.');}connect();}if(!isRoom&&!isDisplay&&!isJoin&&!isDeck&&!state.page&&!state.modal){const header=root.querySelector('.header-right');header.innerHTML=profileControl();header.querySelector('button').addEventListener('click',()=>setModal(state.profile?'profile':'login'));}else if(isRoom||isDisplay||state.profile||!state.page)render();}catch(e){state.error=e.message;render();toast(e.message);}

if(new URLSearchParams(location.search).get('auth')==='failed')toast('Sign-in could not finish. Please try again.');
